def f(S, N, operations):    
    mp = {}
    ans = 0
    for i in range(N):
        l, r = operations[i]
        if l not in mp:
            mp[l] = mp.get(l-1, 0) + 1
        if r not in mp:
            mp[r] = mp.get(r-1, 0) + 1
    for idx, val in enumerate(S):
        if idx+1 in mp:
            ans += mp[idx+1] * (ord(val)-96)
    return ans
```

